#!/usr/bin/env node
// F 项（2026-10-30，吸收竞品 opencode-qq bin/setup.mjs 的零依赖思路）：
// 扫码绑定引导——动态 import 官方 @tencent-connect/qqbot-connector（不进
// dependencies，守红线：官方包只做参考/用户自选安装），手机 QQ 扫码拿到
// appId/appSecret 后合并写入 ~/.openqq/.env（保留其余既有配置行）。
import fs from "node:fs"
import path from "node:path"
import os from "node:os"

const CONFIG_DIR = path.join(os.homedir(), ".openqq")
const ENV_FILE = path.join(CONFIG_DIR, ".env")

let connector
try {
  connector = await import("@tencent-connect/qqbot-connector")
} catch {
  console.error("缺少依赖 @tencent-connect/qqbot-connector")
  console.error("请先执行: npm install -g @tencent-connect/qqbot-connector")
  process.exit(1)
}

console.log("请使用手机 QQ 扫描终端二维码完成绑定…")
const credsList = await connector.qrConnect({ source: "opencode-qqbot" })
const creds = credsList?.[0]
if (!creds?.appId || !creds?.appSecret) {
  console.error("扫码未返回凭据")
  process.exit(1)
}

// 合并写入 .env：替换已有 QQ_APP_ID/QQ_APP_SECRET 行，其余行原样保留
let lines = []
try {
  lines = fs.readFileSync(ENV_FILE, "utf8").split("\n")
} catch {
  /* 首次运行无文件 */
}
const seen = new Set()
const merged = lines.map((line) => {
  const m = /^\s*(QQ_APP_ID|QQ_APP_SECRET)\s*=/.exec(line)
  if (!m) return line
  seen.add(m[1])
  return m[1] === "QQ_APP_ID" ? `QQ_APP_ID=${creds.appId}` : `QQ_APP_SECRET=${creds.appSecret}`
})
if (!seen.has("QQ_APP_ID")) merged.push(`QQ_APP_ID=${creds.appId}`)
if (!seen.has("QQ_APP_SECRET")) merged.push(`QQ_APP_SECRET=${creds.appSecret}`)

fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 })
fs.writeFileSync(ENV_FILE, merged.join("\n"), { mode: 0o600 })
console.log(`凭据已写入 ${ENV_FILE}`)
console.log("现在可以运行 openqq 启动 bot 了。")

#!/usr/bin/env node
// openqq 入口（2026-11-02 应用者体验补齐）：运行时自适应——
//   有 bun → bun run src/index.ts（源码语义，dev 友好）
//   无 bun → node dist/openqq-bot.js（发布 bundle，零额外依赖）
// 应用者 npm i -g 后只有 node 也能跑；开发者有 bun 时始终跑源码。
// 注意：本文件必须保持纯 JS（无类型标注）——node 用户直接执行它。
// 2026-11-05 外部提案 Part1 采纳：新增 `openqq notify` 子命令分发（只入队不发送）。
import { spawnSync } from "node:child_process"
import { existsSync } from "node:fs"
import { fileURLToPath } from "node:url"
import { join, dirname } from "node:path"

const root = join(dirname(fileURLToPath(import.meta.url)), "..")

// 2026-11-09 架构红线：看门狗/重启/自启注册都是包内 TS 产物，经本 shim 统一分发。
// 传参不改变无参数行为。
function runChild(cmd, args) {
  const r = spawnSync(cmd, args, { stdio: "inherit" })
  process.exit(r.status ?? 1)
}
if (argv[0] === "watchdog") {
  runChild(detectBun() ?? "node", [join(root, "dist", "openqq-watchdog.js"), ...argv.slice(1)])
}
if (argv[0] === "restart" || argv[0] === "service") {
  runChild("node", [join(root, "dist", "openqq-cli.js"), ...argv])
}

// notify 子命令分发（不改变无参数行为）：CLI 只入队 ~openqq/outbox.json，
// 发送由 bot 进程 notify-sink 消费；CLI 不联网不取 token 不抢锁。
const argv = process.argv.slice(2)
if (argv[0] === "notify") {
  const notifyArgs = argv.slice(1)
  const cliDist = join(root, "dist", "notify-cli.js")
  const cliSrc = join(root, "src", "cli", "notify.ts")
  const bun = detectBun()
  if (existsSync(cliDist)) {
    const r = spawnSync("node", [cliDist, ...notifyArgs], { stdio: "inherit" })
    process.exit(r.status ?? 1)
  }
  if (bun && existsSync(cliSrc)) {
    const r = spawnSync(bun, ["run", cliSrc, ...notifyArgs], { stdio: "inherit" })
    process.exit(r.status ?? 1)
  }
  console.error("[openqq] notify CLI 不存在（包安装不完整，请重装 @linjz/opencode-qqbot）")
  process.exit(1)
}

// bun 探测要覆盖全形态：npm 装的 bun 在 PATH 上只有 bun.ps1（CreateProcess 起不来），
// 真正可执行体在 npm\bun 包内 bin\bun.exe；官方安装则直接是 bun/bun.exe。
function detectBun() {
  const candidates = ["bun", "bun.exe", "bun.cmd", "bun.bat"]
  if (process.platform === "win32") {
    const appdata = process.env.APPDATA || join(process.env.USERPROFILE || "", "AppData", "Roaming")
    candidates.push(join(appdata, "npm", "node_modules", "bun", "bin", "bun.exe"))
  } else {
    candidates.push("/usr/local/bin/bun", "/opt/homebrew/bin/bun", join(process.env.HOME || "", ".bun", "bin", "bun"))
  }
  for (const c of candidates) {
    try {
      const r = spawnSync(c, ["--version"], { stdio: "ignore" })
